    /// <summary>
    /// Processes complete 1-lane inverse batches along input columns.
    /// </summary>
    /// <param name="length">The number of positions in each transform.</param>
    /// <param name="count">The number of independent transforms.</param>
    /// <param name="source">The borrowed source matrix.</param>
    /// <param name="sourceStride">The source row stride, in floats.</param>
    /// <param name="destination">The borrowed output matrix.</param>
    /// <param name="destinationStride">The destination row stride, in floats.</param>
    /// <param name="first">The first independent transform not already processed by a wider batch.</param>
    /// <param name="workspace">Borrowed storage for two length-by-1 banks. Only the first bank needs initialized inputs.</param>
    /// <returns>The first independent transform left after the complete batches.</returns>
    private static int InverseColumnsScalar(
        int length,
        int count,
        ReadOnlySpan<float> source,
        int sourceStride,
        Span<float> destination,
        int destinationStride,
        int first,
        Span<float> workspace)
    {
        Span<float> values = workspace[..length];
        Span<float> scratch = workspace.Slice(length, length);
        ref float input = ref MemoryMarshal.GetReference(source);
        ref float output = ref MemoryMarshal.GetReference(destination);

        for (; first <= count - 1; first += 1)
        {
            // One vector covers adjacent columns at the same transform position. Physical strides never enter the coefficient-bank layout.
            for (int i = 0; i < length; i++)
            {
                values[i] = Unsafe.Add(ref input, (i * sourceStride) + first);
            }

            Inverse(values, scratch);
            for (int i = 0; i < length; i++)
            {
                Unsafe.Add(ref output, (i * destinationStride) + first) = values[i];
            }
        }

        return first;
    }

    /// <summary>
    /// Processes complete 1-lane inverse batches along input rows.
    /// </summary>
    /// <param name="length">The number of positions in each transform.</param>
    /// <param name="count">The number of independent transforms.</param>
    /// <param name="source">The borrowed source matrix.</param>
    /// <param name="sourceStride">The source row stride, in floats.</param>
    /// <param name="destination">The borrowed output matrix.</param>
    /// <param name="destinationStride">The destination row stride, in floats.</param>
    /// <param name="transposed">Whether transform positions become output rows and input rows become output columns.</param>
    /// <param name="first">The first independent transform not already processed by a wider batch.</param>
    /// <param name="workspace">Borrowed storage for two length-by-1 banks. Only the first bank needs initialized inputs.</param>
    /// <returns>The first independent transform left after the complete batches.</returns>
    private static int InverseRowsScalar(
        int length,
        int count,
        ReadOnlySpan<float> source,
        int sourceStride,
        Span<float> destination,
        int destinationStride,
        bool transposed,
        int first,
        Span<float> workspace)
    {
        Span<float> values = workspace[..length];
        Span<float> scratch = workspace.Slice(length, length);
        ref float input = ref MemoryMarshal.GetReference(source);
        ref float output = ref MemoryMarshal.GetReference(destination);

        for (; first <= count - 1; first += 1)
        {
            source.Slice(first * sourceStride, length).CopyTo(values);

            Inverse(values, scratch);
            if (transposed)
            {
                // A complete vector is one contiguous output row. Only logical samples are stored; destination padding remains untouched.
                for (int i = 0; i < length; i++)
                {
                    Unsafe.Add(ref output, (i * destinationStride) + first) = values[i];
                }
            }
            else
            {
                for (int i = 0; i < length; i++)
                {
                    Unsafe.Add(ref output, (first * destinationStride) + i) = values[i];
                }
            }
        }

        return first;
    }

    /// <summary>
    /// Computes independent forward transforms using two nonoverlapping borrowed vector banks.
    /// </summary>
    /// <param name="values">One vector per transform position. Its length is a power of two from one through 256.</param>
    /// <param name="scratch">At least values.Length vectors. Previous contents are not read.</param>
    private static void Forward(Span<Vector128<float>> values, Span<Vector128<float>> scratch)
    {
        // Small transforms stay in registers. The one-point transform is an identity and must not copy any trailing samples.
        switch (values.Length)
        {
            case 1:
                return;
            case 2:
                Forward2(values);
                return;
            case 4:
                Forward4(values);
                return;
            case 8:
                Forward8(values);
                return;
            case 16:
                Forward16(values);
                return;
            case 32:
                Forward32(values);
                return;
        }

        int half = values.Length / 2;
        ReadOnlySpan<float> weights = JxlDctScales.GetMultipliers(values.Length);

        // Consume both original halves before reusing their bank as recursive scratch. Neither recursive call can then destroy unread input.
        for (int i = 0; i < half; i++)
        {
            Vector128<float> first = values[i];
            Vector128<float> last = values[values.Length - i - 1];
            scratch[i] = first + last;
            scratch[half + i] = (first - last) * Vector128.Create(weights[i]);
        }

        Forward(scratch[..half], values);
        Forward(scratch.Slice(half, half), values);
        scratch[half] = Vector128.MultiplyAddEstimate(scratch[half], Vector128.Create(JxlDctScales.Sqrt2), scratch[half + 1]);

        for (int i = 1; i + 1 < half; i++)
        {
            scratch[half + i] += scratch[half + i + 1];
        }

        for (int i = 0; i < half; i++)
        {
            values[2 * i] = scratch[i];
            values[(2 * i) + 1] = scratch[half + i];
        }
    }

    /// <summary>
    /// Computes independent 2-point forward transforms without intermediate memory passes.
    /// </summary>
    /// <param name="values">Exactly 2 position vectors, replaced with the transform results. Each lane remains independent.</param>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private static void Forward2(Span<Vector128<float>> values)
    {
        // The Perera-Liu radix-two factors retain libjxl's coefficient bits and multiply-add sites.
        // Load every input before publishing any result. This also permits the larger workers to transform a bank in place.
        Vector128<float> input0 = values[0];
        Vector128<float> input1 = values[1];

        Vector128<float> v0 = input0 + input1;
        Vector128<float> v1 = input0 - input1;

        values[0] = v0;
        values[1] = v1;
    }

    /// <summary>
    /// Computes independent 4-point forward transforms without intermediate memory passes.
    /// </summary>
    /// <param name="values">Exactly 4 position vectors, replaced with the transform results. Each lane remains independent.</param>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private static void Forward4(Span<Vector128<float>> values)
    {
        // The Perera-Liu radix-two factors retain libjxl's coefficient bits and multiply-add sites.
        // Load every input before publishing any result. This also permits the larger workers to transform a bank in place.
        Vector128<float> input0 = values[0];
        Vector128<float> input1 = values[1];
        Vector128<float> input2 = values[2];
        Vector128<float> input3 = values[3];

        Vector128<float> v0 = input0 + input3;
        Vector128<float> v1 = (input0 - input3) * Vector128.Create(0.541196100146197f);
        Vector128<float> v2 = input1 + input2;
        Vector128<float> v3 = (input1 - input2) * Vector128.Create(1.3065629648763764f);
        Vector128<float> v4 = v0 + v2;
        Vector128<float> v5 = v0 - v2;
        Vector128<float> v6 = v1 + v3;
        Vector128<float> v7 = v1 - v3;
        Vector128<float> v8 = Vector128.MultiplyAddEstimate(v6, Vector128.Create(JxlDctScales.Sqrt2), v7);

        values[0] = v4;
        values[1] = v8;
        values[2] = v5;
        values[3] = v7;
    }

    /// <summary>
    /// Computes independent 8-point forward transforms without intermediate memory passes.
    /// </summary>
    /// <param name="values">Exactly 8 position vectors, replaced with the transform results. Each lane remains independent.</param>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private static void Forward8(Span<Vector128<float>> values)
    {
        // The Perera-Liu radix-two factors retain libjxl's coefficient bits and multiply-add sites.
        // Load every input before publishing any result. This also permits the larger workers to transform a bank in place.
        Vector128<float> input0 = values[0];
        Vector128<float> input1 = values[1];
        Vector128<float> input2 = values[2];
        Vector128<float> input3 = values[3];
        Vector128<float> input4 = values[4];
        Vector128<float> input5 = values[5];
        Vector128<float> input6 = values[6];
        Vector128<float> input7 = values[7];

        Vector128<float> v0 = input0 + input7;
        Vector128<float> v1 = (input0 - input7) * Vector128.Create(0.5097955791041592f);
        Vector128<float> v2 = input1 + input6;
        Vector128<float> v3 = (input1 - input6) * Vector128.Create(0.6013448869350453f);
        Vector128<float> v4 = input2 + input5;
        Vector128<float> v5 = (input2 - input5) * Vector128.Create(0.8999762231364156f);
        Vector128<float> v6 = input3 + input4;
        Vector128<float> v7 = (input3 - input4) * Vector128.Create(2.5629154477415055f);
        Vector128<float> v8 = v0 + v6;
        Vector128<float> v9 = (v0 - v6) * Vector128.Create(0.541196100146197f);
        Vector128<float> v10 = v2 + v4;
        Vector128<float> v11 = (v2 - v4) * Vector128.Create(1.3065629648763764f);
        Vector128<float> v12 = v8 + v10;
        Vector128<float> v13 = v8 - v10;
        Vector128<float> v14 = v9 + v11;
        Vector128<float> v15 = v9 - v11;
        Vector128<float> v16 = Vector128.MultiplyAddEstimate(v14, Vector128.Create(JxlDctScales.Sqrt2), v15);
        Vector128<float> v17 = v1 + v7;
        Vector128<float> v18 = (v1 - v7) * Vector128.Create(0.541196100146197f);
        Vector128<float> v19 = v3 + v5;
        Vector128<float> v20 = (v3 - v5) * Vector128.Create(1.3065629648763764f);
        Vector128<float> v21 = v17 + v19;
        Vector128<float> v22 = v17 - v19;
        Vector128<float> v23 = v18 + v20;
        Vector128<float> v24 = v18 - v20;
        Vector128<float> v25 = Vector128.MultiplyAddEstimate(v23, Vector128.Create(JxlDctScales.Sqrt2), v24);
        Vector128<float> v26 = Vector128.MultiplyAddEstimate(v21, Vector128.Create(JxlDctScales.Sqrt2), v25);
        Vector128<float> v27 = v25 + v22;
