        Vector256<float> v8 = Vector256.MultiplyAddEstimate(v6, Vector256.Create(JxlDctScales.Sqrt2), v7);

        values[0] = v4;
        values[1] = v8;
        values[2] = v5;
        values[3] = v7;
    }

