    /// <summary>
    /// Processes complete 16-lane forward batches along input columns.
    /// </summary>
    /// <param name="length">The number of positions in each transform.</param>
    /// <param name="count">The number of independent transforms.</param>
    /// <param name="source">The borrowed source matrix.</param>
    /// <param name="sourceStride">The source row stride, in floats.</param>
    /// <param name="destination">The borrowed output matrix.</param>
    /// <param name="destinationStride">The destination row stride, in floats.</param>
    /// <param name="first">The first independent transform not already processed by a wider batch.</param>
    /// <param name="workspace">Borrowed storage for two length-by-16 banks. Only the first bank needs initialized inputs.</param>
    /// <returns>The first independent transform left after the complete batches.</returns>
    private static int ForwardColumns512(
        int length,
        int count,
        ReadOnlySpan<float> source,
        int sourceStride,
        Span<float> destination,
        int destinationStride,
        int first,
        Span<float> workspace)
    {
        Span<Vector512<float>> values = MemoryMarshal.Cast<float, Vector512<float>>(workspace[..(length * 16)]);
        Span<Vector512<float>> scratch = MemoryMarshal.Cast<float, Vector512<float>>(workspace.Slice(length * 16, length * 16));
        ref float input = ref MemoryMarshal.GetReference(source);
        ref float output = ref MemoryMarshal.GetReference(destination);
        Vector512<float> scale = Vector512.Create(1F / length);

        for (; first <= count - 16; first += 16)
        {
            // One vector covers adjacent columns at the same transform position. Physical strides never enter the coefficient-bank layout.
            for (int i = 0; i < length; i++)
            {
                values[i] = Vector512.LoadUnsafe(ref input, (nuint)((i * sourceStride) + first));
            }

            Forward(values, scratch);
            for (int i = 0; i < length; i++)
            {
                (values[i] * scale).StoreUnsafe(ref output, (nuint)((i * destinationStride) + first));
            }
        }

        return first;
    }

    /// <summary>
    /// Processes complete 16-lane forward batches along input rows.
    /// </summary>
    /// <param name="length">The number of positions in each transform.</param>
    /// <param name="count">The number of independent transforms.</param>
    /// <param name="source">The borrowed source matrix.</param>
    /// <param name="sourceStride">The source row stride, in floats.</param>
    /// <param name="destination">The borrowed output matrix.</param>
    /// <param name="destinationStride">The destination row stride, in floats.</param>
    /// <param name="transposed">Whether transform positions become output rows and input rows become output columns.</param>
    /// <param name="first">The first independent transform not already processed by a wider batch.</param>
    /// <param name="workspace">Borrowed storage for two length-by-16 banks. Only the first bank needs initialized inputs.</param>
    /// <returns>The first independent transform left after the complete batches.</returns>
    private static int ForwardRows512(
        int length,
        int count,
        ReadOnlySpan<float> source,
        int sourceStride,
        Span<float> destination,
        int destinationStride,
        bool transposed,
        int first,
        Span<float> workspace)
    {
        Span<Vector512<float>> values = MemoryMarshal.Cast<float, Vector512<float>>(workspace[..(length * 16)]);
        Span<Vector512<float>> scratch = MemoryMarshal.Cast<float, Vector512<float>>(workspace.Slice(length * 16, length * 16));
        ref float input = ref MemoryMarshal.GetReference(source);
        ref float output = ref MemoryMarshal.GetReference(destination);
        Vector512<float> scale = Vector512.Create(1F / length);

        for (; first <= count - 16; first += 16)
        {
            // Each square load contains adjacent samples from independent rows. Transposition puts those rows into SIMD lanes.
            // The complete row band is loaded before any same-orientation output is written, so source and destination can be the same matrix.
            for (int column = 0; column < length; column += 16)
            {
                Vector512<int> row0 = Vector512.LoadUnsafe(ref input, (nuint)(((first + 0) * sourceStride) + column)).AsInt32();
                Vector512<int> row1 = Vector512.LoadUnsafe(ref input, (nuint)(((first + 1) * sourceStride) + column)).AsInt32();
                Vector512<int> row2 = Vector512.LoadUnsafe(ref input, (nuint)(((first + 2) * sourceStride) + column)).AsInt32();
                Vector512<int> row3 = Vector512.LoadUnsafe(ref input, (nuint)(((first + 3) * sourceStride) + column)).AsInt32();
                Vector512<int> row4 = Vector512.LoadUnsafe(ref input, (nuint)(((first + 4) * sourceStride) + column)).AsInt32();
                Vector512<int> row5 = Vector512.LoadUnsafe(ref input, (nuint)(((first + 5) * sourceStride) + column)).AsInt32();
                Vector512<int> row6 = Vector512.LoadUnsafe(ref input, (nuint)(((first + 6) * sourceStride) + column)).AsInt32();
                Vector512<int> row7 = Vector512.LoadUnsafe(ref input, (nuint)(((first + 7) * sourceStride) + column)).AsInt32();
                Vector512<int> row8 = Vector512.LoadUnsafe(ref input, (nuint)(((first + 8) * sourceStride) + column)).AsInt32();
                Vector512<int> row9 = Vector512.LoadUnsafe(ref input, (nuint)(((first + 9) * sourceStride) + column)).AsInt32();
                Vector512<int> row10 = Vector512.LoadUnsafe(ref input, (nuint)(((first + 10) * sourceStride) + column)).AsInt32();
                Vector512<int> row11 = Vector512.LoadUnsafe(ref input, (nuint)(((first + 11) * sourceStride) + column)).AsInt32();
                Vector512<int> row12 = Vector512.LoadUnsafe(ref input, (nuint)(((first + 12) * sourceStride) + column)).AsInt32();
                Vector512<int> row13 = Vector512.LoadUnsafe(ref input, (nuint)(((first + 13) * sourceStride) + column)).AsInt32();
                Vector512<int> row14 = Vector512.LoadUnsafe(ref input, (nuint)(((first + 14) * sourceStride) + column)).AsInt32();
                Vector512<int> row15 = Vector512.LoadUnsafe(ref input, (nuint)(((first + 15) * sourceStride) + column)).AsInt32();

                SimdUtils.Transpose(
                    ref row0,
                    ref row1,
                    ref row2,
                    ref row3,
                    ref row4,
                    ref row5,
                    ref row6,
                    ref row7,
                    ref row8,
                    ref row9,
                    ref row10,
                    ref row11,
                    ref row12,
                    ref row13,
                    ref row14,
                    ref row15);

                values[column + 0] = row0.AsSingle();
                values[column + 1] = row1.AsSingle();
                values[column + 2] = row2.AsSingle();
                values[column + 3] = row3.AsSingle();
                values[column + 4] = row4.AsSingle();
                values[column + 5] = row5.AsSingle();
                values[column + 6] = row6.AsSingle();
                values[column + 7] = row7.AsSingle();
                values[column + 8] = row8.AsSingle();
                values[column + 9] = row9.AsSingle();
                values[column + 10] = row10.AsSingle();
                values[column + 11] = row11.AsSingle();
                values[column + 12] = row12.AsSingle();
                values[column + 13] = row13.AsSingle();
                values[column + 14] = row14.AsSingle();
                values[column + 15] = row15.AsSingle();
            }

            Forward(values, scratch);
            if (transposed)
            {
                // A complete vector is one contiguous output row. Only logical samples are stored; destination padding remains untouched.
                for (int i = 0; i < length; i++)
                {
                    (values[i] * scale).StoreUnsafe(ref output, (nuint)((i * destinationStride) + first));
                }
            }
            else
            {
                // Restore row-major order one register tile at a time. This replaces a separate full-block transpose and copy.
                for (int column = 0; column < length; column += 16)
                {
                    Vector512<int> row0 = (values[column + 0] * scale).AsInt32();
                    Vector512<int> row1 = (values[column + 1] * scale).AsInt32();
                    Vector512<int> row2 = (values[column + 2] * scale).AsInt32();
                    Vector512<int> row3 = (values[column + 3] * scale).AsInt32();
                    Vector512<int> row4 = (values[column + 4] * scale).AsInt32();
                    Vector512<int> row5 = (values[column + 5] * scale).AsInt32();
                    Vector512<int> row6 = (values[column + 6] * scale).AsInt32();
                    Vector512<int> row7 = (values[column + 7] * scale).AsInt32();
                    Vector512<int> row8 = (values[column + 8] * scale).AsInt32();
                    Vector512<int> row9 = (values[column + 9] * scale).AsInt32();
                    Vector512<int> row10 = (values[column + 10] * scale).AsInt32();
                    Vector512<int> row11 = (values[column + 11] * scale).AsInt32();
                    Vector512<int> row12 = (values[column + 12] * scale).AsInt32();
                    Vector512<int> row13 = (values[column + 13] * scale).AsInt32();
                    Vector512<int> row14 = (values[column + 14] * scale).AsInt32();
                    Vector512<int> row15 = (values[column + 15] * scale).AsInt32();

                    SimdUtils.Transpose(
                        ref row0,
                        ref row1,
                        ref row2,
                        ref row3,
                        ref row4,
                        ref row5,
                        ref row6,
                        ref row7,
                        ref row8,
                        ref row9,
                        ref row10,
                        ref row11,
                        ref row12,
                        ref row13,
                        ref row14,
                        ref row15);

                    row0.AsSingle().StoreUnsafe(ref output, (nuint)(((first + 0) * destinationStride) + column));
                    row1.AsSingle().StoreUnsafe(ref output, (nuint)(((first + 1) * destinationStride) + column));
                    row2.AsSingle().StoreUnsafe(ref output, (nuint)(((first + 2) * destinationStride) + column));
                    row3.AsSingle().StoreUnsafe(ref output, (nuint)(((first + 3) * destinationStride) + column));
                    row4.AsSingle().StoreUnsafe(ref output, (nuint)(((first + 4) * destinationStride) + column));
                    row5.AsSingle().StoreUnsafe(ref output, (nuint)(((first + 5) * destinationStride) + column));
                    row6.AsSingle().StoreUnsafe(ref output, (nuint)(((first + 6) * destinationStride) + column));
                    row7.AsSingle().StoreUnsafe(ref output, (nuint)(((first + 7) * destinationStride) + column));
                    row8.AsSingle().StoreUnsafe(ref output, (nuint)(((first + 8) * destinationStride) + column));
                    row9.AsSingle().StoreUnsafe(ref output, (nuint)(((first + 9) * destinationStride) + column));
                    row10.AsSingle().StoreUnsafe(ref output, (nuint)(((first + 10) * destinationStride) + column));
                    row11.AsSingle().StoreUnsafe(ref output, (nuint)(((first + 11) * destinationStride) + column));
                    row12.AsSingle().StoreUnsafe(ref output, (nuint)(((first + 12) * destinationStride) + column));
                    row13.AsSingle().StoreUnsafe(ref output, (nuint)(((first + 13) * destinationStride) + column));
                    row14.AsSingle().StoreUnsafe(ref output, (nuint)(((first + 14) * destinationStride) + column));
                    row15.AsSingle().StoreUnsafe(ref output, (nuint)(((first + 15) * destinationStride) + column));
                }
            }
        }

        return first;
    }

    /// <summary>
    /// Computes independent inverse transforms using two nonoverlapping borrowed vector banks.
    /// </summary>
    /// <param name="values">One vector per transform position. Its length is a power of two from one through 256.</param>
    /// <param name="scratch">At least values.Length vectors. Previous contents are not read.</param>
    private static void Inverse(Span<Vector512<float>> values, Span<Vector512<float>> scratch)
    {
        // Small transforms stay in registers. The one-point transform is an identity and must not copy any trailing samples.
        switch (values.Length)
        {
            case 1:
                return;
            case 2:
                Inverse2(values);
                return;
            case 4:
                Inverse4(values);
                return;
            case 8:
                Inverse8(values);
                return;
            case 16:
                Inverse16(values);
                return;
            case 32:
                Inverse32(values);
                return;
        }

        int half = values.Length / 2;
        // Separate frequency parity before either recursive call. The original bank can then serve as recursive scratch.
        for (int i = 0; i < half; i++)
        {
            scratch[i] = values[2 * i];
            scratch[half + i] = values[(2 * i) + 1];
        }

        Inverse(scratch[..half], values);

        // Descend so every odd-frequency predecessor is read before its own entry changes.
        for (int i = half - 1; i > 0; i--)
        {
            scratch[half + i] += scratch[half + i - 1];
        }

        scratch[half] *= Vector512.Create(JxlDctScales.Sqrt2);
        Inverse(scratch.Slice(half, half), values);
        ReadOnlySpan<float> weights = JxlDctScales.GetMultipliers(values.Length);

        for (int i = 0; i < half; i++)
        {
            Vector512<float> weight = Vector512.Create(weights[i]);
            Vector512<float> even = scratch[i];
            Vector512<float> odd = scratch[half + i];
            values[i] = Vector512.MultiplyAddEstimate(weight, odd, even);
            values[values.Length - i - 1] = Vector512.MultiplyAddEstimate(-weight, odd, even);
        }
    }

    /// <summary>
    /// Computes independent 2-point inverse transforms without intermediate memory passes.
    /// </summary>
    /// <param name="values">Exactly 2 position vectors, replaced with the transform results. Each lane remains independent.</param>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private static void Inverse2(Span<Vector512<float>> values)
    {
        // The Perera-Liu radix-two factors retain libjxl's coefficient bits and multiply-add sites.
        // Load every input before publishing any result. This also permits the larger workers to transform a bank in place.
        Vector512<float> input0 = values[0];
        Vector512<float> input1 = values[1];

        Vector512<float> v0 = input0 + input1;
        Vector512<float> v1 = input0 - input1;

        values[0] = v0;
        values[1] = v1;
    }

    /// <summary>
    /// Computes independent 4-point inverse transforms without intermediate memory passes.
    /// </summary>
    /// <param name="values">Exactly 4 position vectors, replaced with the transform results. Each lane remains independent.</param>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private static void Inverse4(Span<Vector512<float>> values)
    {
        // The Perera-Liu radix-two factors retain libjxl's coefficient bits and multiply-add sites.
        // Load every input before publishing any result. This also permits the larger workers to transform a bank in place.
        Vector512<float> input0 = values[0];
        Vector512<float> input1 = values[1];
        Vector512<float> input2 = values[2];
        Vector512<float> input3 = values[3];

        Vector512<float> v0 = input0 + input2;
        Vector512<float> v1 = input0 - input2;
        Vector512<float> v2 = input3 + input1;
        Vector512<float> v3 = input1 * Vector512.Create(JxlDctScales.Sqrt2);
        Vector512<float> v4 = v3 + v2;
        Vector512<float> v5 = v3 - v2;
        Vector512<float> v6 = Vector512.MultiplyAddEstimate(Vector512.Create(0.541196100146197f), v4, v0);
        Vector512<float> v7 = Vector512.MultiplyAddEstimate(-Vector512.Create(0.541196100146197f), v4, v0);
        Vector512<float> v8 = Vector512.MultiplyAddEstimate(Vector512.Create(1.3065629648763764f), v5, v1);
        Vector512<float> v9 = Vector512.MultiplyAddEstimate(-Vector512.Create(1.3065629648763764f), v5, v1);

        values[0] = v6;
        values[1] = v8;
        values[2] = v9;
        values[3] = v7;
    }

    /// <summary>
    /// Computes independent 8-point inverse transforms without intermediate memory passes.
    /// </summary>
    /// <param name="values">Exactly 8 position vectors, replaced with the transform results. Each lane remains independent.</param>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private static void Inverse8(Span<Vector512<float>> values)
    {
        // The Perera-Liu radix-two factors retain libjxl's coefficient bits and multiply-add sites.
        // Load every input before publishing any result. This also permits the larger workers to transform a bank in place.
        Vector512<float> input0 = values[0];
        Vector512<float> input1 = values[1];
        Vector512<float> input2 = values[2];
        Vector512<float> input3 = values[3];
        Vector512<float> input4 = values[4];
        Vector512<float> input5 = values[5];
        Vector512<float> input6 = values[6];
        Vector512<float> input7 = values[7];

        Vector512<float> v0 = input0 + input4;
        Vector512<float> v1 = input0 - input4;
        Vector512<float> v2 = input6 + input2;
        Vector512<float> v3 = input2 * Vector512.Create(JxlDctScales.Sqrt2);
        Vector512<float> v4 = v3 + v2;
        Vector512<float> v5 = v3 - v2;
        Vector512<float> v6 = Vector512.MultiplyAddEstimate(Vector512.Create(0.541196100146197f), v4, v0);
        Vector512<float> v7 = Vector512.MultiplyAddEstimate(-Vector512.Create(0.541196100146197f), v4, v0);
        Vector512<float> v8 = Vector512.MultiplyAddEstimate(Vector512.Create(1.3065629648763764f), v5, v1);
        Vector512<float> v9 = Vector512.MultiplyAddEstimate(-Vector512.Create(1.3065629648763764f), v5, v1);
        Vector512<float> v10 = input7 + input5;
        Vector512<float> v11 = input5 + input3;
        Vector512<float> v12 = input3 + input1;
        Vector512<float> v13 = input1 * Vector512.Create(JxlDctScales.Sqrt2);
        Vector512<float> v14 = v13 + v11;
        Vector512<float> v15 = v13 - v11;
        Vector512<float> v16 = v10 + v12;
        Vector512<float> v17 = v12 * Vector512.Create(JxlDctScales.Sqrt2);
        Vector512<float> v18 = v17 + v16;
        Vector512<float> v19 = v17 - v16;
        Vector512<float> v20 = Vector512.MultiplyAddEstimate(Vector512.Create(0.541196100146197f), v18, v14);
        Vector512<float> v21 = Vector512.MultiplyAddEstimate(-Vector512.Create(0.541196100146197f), v18, v14);
        Vector512<float> v22 = Vector512.MultiplyAddEstimate(Vector512.Create(1.3065629648763764f), v19, v15);
        Vector512<float> v23 = Vector512.MultiplyAddEstimate(-Vector512.Create(1.3065629648763764f), v19, v15);
        Vector512<float> v24 = Vector512.MultiplyAddEstimate(Vector512.Create(0.5097955791041592f), v20, v6);
        Vector512<float> v25 = Vector512.MultiplyAddEstimate(-Vector512.Create(0.5097955791041592f), v20, v6);
        Vector512<float> v26 = Vector512.MultiplyAddEstimate(Vector512.Create(0.6013448869350453f), v22, v8);
        Vector512<float> v27 = Vector512.MultiplyAddEstimate(-Vector512.Create(0.6013448869350453f), v22, v8);
        Vector512<float> v28 = Vector512.MultiplyAddEstimate(Vector512.Create(0.8999762231364156f), v23, v9);
        Vector512<float> v29 = Vector512.MultiplyAddEstimate(-Vector512.Create(0.8999762231364156f), v23, v9);
        Vector512<float> v30 = Vector512.MultiplyAddEstimate(Vector512.Create(2.5629154477415055f), v21, v7);
        Vector512<float> v31 = Vector512.MultiplyAddEstimate(-Vector512.Create(2.5629154477415055f), v21, v7);

        values[0] = v24;
        values[1] = v26;
        values[2] = v28;
        values[3] = v30;
        values[4] = v31;
        values[5] = v29;
        values[6] = v27;
        values[7] = v25;
    }

    /// <summary>
